#!/usr/bin/env python3
"""Render the fixed exploratory snapshot using the site's existing English design."""
import html,json,sys
from pathlib import Path
from preview_gate import preview_gate
p=Path(sys.argv[1] if len(sys.argv)>1 else 'EuroJackpot');r=json.loads((p/'numerology-study-20261013.json').read_text());e=html.escape
freq=''.join(f'<tr><td>{x["root"]}</td><td>{x["main_root"]}</td><td>{x["star_root"]}</td><td>{x["all_root"]}</td></tr>' for x in r['frequencies'])
names={'date_root':'Full calendar date','day_root':'Day of month','month_root':'Calendar month','year_root':'Calendar year','main_root':'Five main numbers','star_root':'Two Euro numbers','all_root':'All seven numbers'}
matches=''.join(f'<tr><td>{names[x["dateFactor"]]}</td><td>{names[x["outcome"]]}</td><td>{x["observed"]}</td><td>{x["expected"]:.1f}</td><td>{x["percent"]:.2f}%</td></tr>' for x in r['matches'])
raw=''.join('<article class="card"><h3>'+names[k.replace('_sum','_root')]+'</h3><table><thead><tr><th>Raw sum</th><th>Draws</th><th>Reduced root</th></tr></thead><tbody>'+''.join(f'<tr><td>{x["sum"]}</td><td>{x["count"]}</td><td>{1+(x["sum"]-1)%9}</td></tr>' for x in r['rawSums'][k][:10])+'</tbody></table></article>' for k in ['main_sum','star_sum','all_sum'])
tests=''.join(f'<tr><td>{e(x["kind"])}</td><td>{names.get(x.get("dateFactor"),"—")}</td><td>{names[x["outcome"]]}</td><td>{x["p"]:.4f}</td><td>{x["pHolm"]:.4f}</td></tr>' for x in r['tests'])
payload=json.dumps(r,separators=(',',':')).replace('<','\\u003c')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EuroJackpot Numerology: Draw Dates, Number Sums &amp; Patterns | SETAEI</title><meta name="description" content="Explore numerology across 998 EuroJackpot draws. Compare date numbers with sums of five main numbers, two Euro numbers and all seven, with fair-draw baselines."><link rel="canonical" href="https://setai.no/EuroJackpot/numerology-study-20261013.html"><meta property="og:image" content="https://setai.no/EuroJackpot/social.png"><link rel="stylesheet" href="style.css?v=2"><style>.root-bars{display:grid;gap:14px}.root-bar{display:grid;grid-template-columns:25px 1fr 85px;align-items:center;gap:12px}.tracks{display:grid;gap:3px}.track{height:9px;display:block;border-radius:3px}.observed{background:#88ddbe}.expected{background:#b2a8d8}.root-matrix td{min-width:40px;text-align:center}.root-matrix th{white-space:nowrap}.study-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:16px}select{max-width:100%}section{scroll-margin-top:100px}</style></head><body><header class="topbar"><div class="wrap nav"><a class="logo" href="/">SETAEI</a><nav class="navlinks"><a href="./#trekninger">Your ticket</a><a href="results.html">Results</a><a href="eksperiment.html">Research</a></nav></div></header><main class="wrap"><div class="hero"><div><div class="eyebrow">Numerology study · fixed archive snapshot</div><h1>Dates and sums.<br><em>Do the numbers connect?</em></h1><p>Every draw from 23 March 2012 through 13 October 2026. We reduce the date and the winning-number sums to 1–9, count patterns, and compare them with fair independent draws.</p></div></div><div class="meta"><div><strong>998</strong><small>Draws examined</small></div><div><strong>27</strong><small>Tests corrected together</small></div><div><strong>0</strong><small>Tests significant after correction</small></div></div><section><h2>How each number is calculated</h2><div class="card"><p>Keep adding the digits until one digit remains. We use 1–9, without retaining master numbers 11, 22 or 33, matching the reduction used for personal year, month and day in our calculator.</p><table><thead><tr><th>13 October 2026 example</th><th>Calculation</th><th>Root</th></tr></thead><tbody><tr><td>Full calendar date</td><td>1+3+1+0+2+0+2+6 = 15 → 1+5</td><td>6</td></tr><tr><td>Five main numbers</td><td>11+17+20+22+35 = 105 → 1+0+5</td><td>6</td></tr><tr><td>Two Euro numbers</td><td>4+8 = 12 → 1+2</td><td>3</td></tr><tr><td>All seven numbers</td><td>105+12 = 117 → 1+1+7</td><td>9</td></tr></tbody></table><p>The date and main-number roots matched in this draw. Across all draws they matched 118 times, compared with 110.9 expected under the fair-draw baseline.</p></div></section><section><div class="bar"><h2>Which sum roots appear most?</h2><label>Number group <select id="root-pool"><option value="main_root">Five main numbers</option><option value="star_root">Two Euro numbers</option><option value="all_root" selected>All seven numbers</option></select></label></div><div class="card"><div id="root-bars" class="root-bars" aria-label="Observed and expected root counts"></div><p class="tiny">Mint: observed draws. Purple: mathematical expected count. Each row shows observed / expected. Both bars use the same scale beginning at zero. These are counts of drawn combinations, not counts of people who won.</p><div class="table-scroll"><table><thead><tr><th>Root</th><th>Five main numbers</th><th>Two Euro numbers</th><th>All seven</th></tr></thead><tbody>FREQUENCIES</tbody></table></div></div></section><section><h2>Exact date-to-sum matches</h2><div class="card table-scroll"><table><thead><tr><th>Date factor</th><th>Sum group</th><th>Observed matches</th><th>Expected matches</th><th>Observed share</th></tr></thead><tbody>MATCHES</tbody></table><p class="tiny">Expectation uses each draw's applicable Euro-number pool. A descriptive surplus or deficit is not proof of a prediction rule.</p></div></section><section><div class="bar"><h2>Explore the relationship</h2><label>Date factor <select id="date-factor"><option value="date_root">Full calendar date</option><option value="day_root">Day of month</option><option value="month_root">Calendar month</option><option value="year_root">Calendar year</option></select></label><label>Sum group <select id="matrix-pool"><option value="main_root">Five main numbers</option><option value="star_root">Two Euro numbers</option><option value="all_root" selected>All seven numbers</option></select></label></div><div class="card"><p class="tiny">Rows: date-factor root. Columns: winning-sum root. Each cell is the number of matching draw records for that pair, including non-equal pairs.</p><div class="table-scroll" id="root-matrix"></div><p id="matrix-summary" class="tiny" aria-live="polite"></p></div></section><section><h2>The most common unreduced sums</h2><p>These rankings describe the sums before digit reduction. Raw sums naturally have different chances because some can be formed by many more legal combinations.</p><div class="study-grid">RAW</div></section><section><h2>What about your personal day?</h2><div class="card"><p>The calculator's personal day also uses your birth day and birth month. Algebraically it is the full-date root shifted around the 1–9 cycle by (birth day + birth month) modulo 9. Changing the birthday relabels the same calendar cycle; it does not add independent information about a lottery draw. Birth year and name are not used in this particular daily-number formula.</p><p>A full seven-number root is likewise determined by the main and Euro sum roots: reduce(main root + Euro root). Those three views are related, so a coincidence across them cannot count as three independent discoveries.</p></div></section><section><h2>Did we find evidence of a connection?</h2><div class="card"><p><strong>No robust association was found after correcting the 27 comparisons together.</strong> The tests covered overall root frequencies, full-date/day/month/year relationships, and exact equal-root matches. This is an exploratory analysis of an archive already examined in earlier studies.</p><p>For fairness, the baseline counts every possible five-of-50 main-number sum exactly and every two-number Euro sum under the historical pools of 8, 10 and 12. Overall frequency tests use 50,000 null simulations per sum group. Date-association tests use 9,999 permutations within the historical pool regimes. Equal-root counts use a Poisson-binomial test. Holm correction applies to all 27 comparisons.</p><p>The most frequent root is not necessarily more likely in the next draw. Any proposed prediction rule needs to be fixed before testing it on new results. No new number-selection strategy is adopted from these rankings.</p><details><summary>Inspect every test</summary><div class="table-scroll"><table><thead><tr><th>Test</th><th>Date factor</th><th>Sum group</th><th>Unadjusted p</th><th>Holm-adjusted p</th></tr></thead><tbody>TESTS</tbody></table></div></details></div></section><section><h2>Open records</h2><p><a class="audit-link" href="numerology-draws-20261013.csv">Download every draw and calculated number (CSV)</a> · <a class="audit-link" href="numerology-study-20261013.json">Full test results, matrix data and mathematical baseline (JSON)</a> · <a class="audit-link" href="https://www.westlotto.de/service/downloads/downloads.html">Official source</a></p><p class="tiny">Snapshot through 13 October 2026; this dated study does not automatically include subsequent draws. The main lab and its results archive continue updating separately.</p><p><a class="button-link primary" href="./#trekninger">Return to your current ticket →</a></p></section></main><footer><div class="wrap footerinner"><span>SETAEI · Explore patterns. Measure the evidence.</span><a href="./">Back to the lab</a></div></footer><script id="root-study-data" type="application/json">PAYLOAD</script><script>
const report=JSON.parse(document.getElementById('root-study-data').textContent);
function bars(){const k=document.getElementById('root-pool').value,m=Math.max(...report.frequencies.flatMap(x=>[x[k],x[k+'_expected']]));document.getElementById('root-bars').innerHTML=report.frequencies.map(x=>`<div class="root-bar"><strong>${x.root}</strong><div class="tracks"><span class="track observed" style="width:${100*x[k]/m}%"></span><span class="track expected" style="width:${100*x[k+'_expected']/m}%"></span></div><span>${x[k]} / ${x[k+'_expected'].toFixed(1)}</span></div>`).join('');}
function matrix(){const f=document.getElementById('date-factor').value,k=document.getElementById('matrix-pool').value,t=report.associationTables[f][k],max=Math.max(...t.flat());document.getElementById('root-matrix').innerHTML='<table class="root-matrix"><thead><tr><th>Date / sum</th>'+Array.from({length:9},(_,i)=>'<th>'+(i+1)+'</th>').join('')+'<th>Total</th></tr></thead><tbody>'+t.map((row,i)=>'<tr><th>'+(i+1)+'</th>'+row.map(n=>`<td style="background:rgba(136,221,190,${.05+.4*n/max})">${n}</td>`).join('')+'<td>'+row.reduce((a,b)=>a+b,0)+'</td></tr>').join('')+'</tbody></table>';const test=report.tests.find(x=>x.kind==='Date / sum-root association'&&x.dateFactor===f&&x.outcome===k);document.getElementById('matrix-summary').textContent='Within-regime permutation p: '+test.p.toFixed(4)+' · Holm-adjusted p across 27 tests: '+test.pHolm.toFixed(4);}
document.getElementById('root-pool').addEventListener('change',bars);document.getElementById('date-factor').addEventListener('change',matrix);document.getElementById('matrix-pool').addEventListener('change',matrix);bars();matrix();
</script></body></html>'''
for k,v in {'FREQUENCIES':freq,'MATCHES':matches,'RAW':raw,'TESTS':tests,'PAYLOAD':payload}.items():page=page.replace(k,v)
assert 'FREQUENCIES' not in page and 'PAYLOAD' not in page
(p/'numerology-study-20261013.html').write_text(preview_gate(page))
print('Rendered English numerology study, accessible frequency counts, selectable matrix and raw sums.')
